/* @lc app=leetcode id=3382 lang=kotlin */ class Solution { fun ad(t: IntArray, i: Int) = generateSequence(i) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it]++ } fun qs(t: IntArray, i: Int): Int = generateSequence(i) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { t[it] } fun maxRectangleArea(xCoord: IntArray, yCoord: IntArray): Long = xCoord.indices.sortedWith(compareBy<Int>({ xCoord[it] }, { yCoord[it] })).let { ord -> yCoord.toSortedSet().toList().let { ys -> (ys.size + 1).let { m -> IntArray(m).let { bit -> HashMap<Long, LongArray>().let { mp -> ord.groupBy { xCoord[it] }.entries.fold(-1L) { best, (x, grp) -> grp.map { ys.binarySearch(yCoord[it]) + 1 }.let { rk -> rk.zipWithNext().let { prs -> (prs.maxOfOrNull { (a, b) -> mp[a.toLong() * m + b]?.let { r -> if (qs(bit, b) - qs(bit, a - 1) - r[1] == 0L) (x - r[0]) * (ys[b - 1] - ys[a - 1]).toLong() else -1L } ?: -1L } ?: -1L).let { cand -> rk.forEach { ad(bit, it) }.let { prs.forEach { (a, b) -> mp[a.toLong() * m + b] = longArrayOf(x.toLong(), (qs(bit, b) - qs(bit, a - 1)).toLong()) } }.let { maxOf(best, cand) } } } } } } } } } } }